/**
 * Story 369 (consistency-05, pwa-nutrition-03) — the one reading of an Open Food Facts product or
 * search hit, for the PWA and the server alike.
 *
 * They had drifted apart. The server chained names with `??`, so `product_name: ''` never reached
 * the localized name and the hit was dropped; the PWA chained with `||` and kept it. The PWA turned
 * an unreported nutrient into 0, the server left it unknown. And the PWA's default serving called
 * anything with "milk" or "water" in a category a drink — a kilogram tub of yoghurt, a milk
 * chocolate bar, a watermelon — and offered the whole package.
 */
import type { FoodItem } from '../types/health.js';

/** Per 100 g (or 100 ml), as OFF reports it — sodium in grams. Absent means unknown. */
export interface OffNutritionPer100g {
    calories_per_100g?: number;
    protein_per_100g?: number;
    carbs_per_100g?: number;
    fat_per_100g?: number;
    fiber_per_100g?: number;
    sugar_per_100g?: number;
    sodium_per_100g?: number;
}

/** The fields the default serving reads. A raw hit and a mapped product both carry them. */
export interface OffServingFields {
    serving_quantity?: unknown;
    serving_size?: unknown;
    product_quantity?: unknown;
    categories_tags?: unknown;
}

const NAME_FIELDS = ['product_name', 'product_name_en', 'product_name_nl', 'product_name_de'] as const;

/** The first non-blank name, trimmed; null when OFF has none. */
export function offProductName(product: Partial<Record<typeof NAME_FIELDS[number], unknown>>): string | null {
    for (const field of NAME_FIELDS) {
        const value = product[field];
        if (typeof value === 'string' && value.trim()) return value.trim();
    }
    return null;
}

/** Search answers `brands` as an array, the product endpoint as a comma string. */
export function offBrands(brands: unknown): string | undefined {
    const joined = Array.isArray(brands) ? brands.join(', ') : brands;
    return typeof joined === 'string' && joined.trim() ? joined.trim() : undefined;
}

function finite(value: unknown): number | undefined {
    return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

export function offNutritionPer100g(nutriments: Record<string, unknown> | undefined): OffNutritionPer100g {
    const n = nutriments ?? {};
    return {
        calories_per_100g: finite(n['energy-kcal_100g']),
        protein_per_100g: finite(n['proteins_100g']),
        carbs_per_100g: finite(n['carbohydrates_100g']),
        fat_per_100g: finite(n['fat_100g']),
        fiber_per_100g: finite(n['fiber_100g']),
        sugar_per_100g: finite(n['sugars_100g']),
        sodium_per_100g: finite(n['sodium_100g']),
    };
}

type FoodItemNutrition = Pick<FoodItem,
    'base_amount' | 'base_unit' | 'calories_per_base' | 'protein_g_per_base' | 'carbs_g_per_base'
    | 'fat_g_per_base' | 'fiber_g_per_base' | 'sugar_g_per_base' | 'sodium_mg_per_base'>;

/** A food item's nutrition columns, per 100 g, sodium in mg. Unknown stays unknown. */
export function offNutritionToFoodItem(n: OffNutritionPer100g): FoodItemNutrition {
    return {
        base_amount: 100,
        base_unit: 'g',
        calories_per_base: n.calories_per_100g,
        protein_g_per_base: n.protein_per_100g,
        carbs_g_per_base: n.carbs_per_100g,
        fat_g_per_base: n.fat_per_100g,
        fiber_g_per_base: n.fiber_per_100g,
        sugar_g_per_base: n.sugar_per_100g,
        sodium_mg_per_base: n.sodium_per_100g === undefined ? undefined : n.sodium_per_100g * 1000,
    };
}

/**
 * Whole tags only. OFF lists every ancestor, so `en:beverages` covers juices, sodas and waters; the
 * milks sit under dairies and are named on their own. A substring test matched
 * `en:fermented-milk-products` and `en:plant-based-foods-and-beverages`.
 */
const DRINK_TAGS = new Set(['en:beverages', 'en:waters', 'en:milks', 'en:plant-based-milks', 'en:plant-based-beverages']);

/** A drink this size or smaller is drunk in one go; a carton or a 1.5 L bottle is not. */
const SINGLE_SERVE_ML = 500;

function positive(value: unknown): number | undefined {
    const n = typeof value === 'string' && value.trim() ? Number(value) : value;
    return typeof n === 'number' && Number.isFinite(n) && n > 0 ? n : undefined;
}

function oneDecimal(value: number): number {
    return Math.round(value * 10) / 10;
}

/** The amount (g or ml) a new food from OFF offers first. */
export function offDefaultServing(product: OffServingFields): number {
    const tags = Array.isArray(product.categories_tags) ? product.categories_tags : [];
    const isDrink = tags.some((tag) => DRINK_TAGS.has(tag));
    const packageSize = positive(product.product_quantity);

    if (isDrink && packageSize && packageSize <= SINGLE_SERVE_ML) return oneDecimal(packageSize);

    const servingQuantity = positive(product.serving_quantity);
    if (servingQuantity) return oneDecimal(servingQuantity);

    const parsed = typeof product.serving_size === 'string' ? parseOffServingSize(product.serving_size) : null;
    if (parsed) return oneDecimal(parsed);

    // A bar or a snack bag: the package is the serving.
    if (packageSize && packageSize <= 100) return oneDecimal(packageSize);

    return 100;
}

const UNIT_TO_BASE: Record<string, number> = { g: 1, gr: 1, gram: 1, grams: 1, ml: 1, cl: 10, l: 1000 };
const AMOUNT = String.raw`(\d+(?:\.\d+)?)\s*(grams|gram|gr|g|ml|cl|l)\b`;

/**
 * "1 portie (12,5 g)" → 12.5, "25 cl" → 250. A number needs a unit: "1 slice" says nothing about
 * grams, and reading it as 1 g is how a tub defaulted to 1.
 */
export function parseOffServingSize(serving: string): number | null {
    const text = serving.replace(/(\d),(\d)/g, '$1.$2').toLowerCase();
    const match = text.match(new RegExp(String.raw`\(\s*${AMOUNT}\s*\)`)) ?? text.match(new RegExp(AMOUNT));
    if (!match) return null;
    const amount = Number(match[1]) * UNIT_TO_BASE[match[2]];
    return amount > 0 ? amount : null;
}
